pe":"text","text":"Which statement correctly distinguishes a recursive formula from an explicit formula?"}]}]},"e":"A recursive formula defines each new term from the term(s) before it and must state the initial term $u_1$; giving $u_n$ directly in $n$ is what an explicit formula does.","m":1,"df":"easy","tp":"Communicating formulae","st":"recursive vs explicit","cfg":{"question_number":7,"paper_question_key":7,"paper_section":"A","myp_criterion":"C","criterion_label":"Criterion C — Communicating","criterion_title":"Communicating","difficulty_level":"basic","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp5-sequences-and-series-summative-2026"}},{"n":8,"t":"single_choice","p":"Find the missing terms $x$ and $y$ in the arithmetic sequence 7, $x$, $y$, 28.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the missing terms "},{"type":"mathInline","attrs":{"latex":"x"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"y"}},{"type":"text","text":" in the arithmetic sequence 7, "},{"type":"mathInline","attrs":{"latex":"x"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"y"}},{"type":"text","text":", 28."}]}]},"e":"$d = \\frac{28 - 7}{3} = 7$, so the sequence is 7, 14, 21, 28 and $x = 14$, $y = 21$.","m":1,"df":"easy","tp":"Arithmetic sequences","st":"missing terms","cfg":{"question_number":8,"paper_question_key":8,"paper_section":"A","myp_criterion":"A","criterion_label":"Criterion A — Knowing and understanding","criterion_title":"Knowing and understanding","difficulty_level":"basic","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp5-sequences-and-series-summative-2026"}},{"n":9,"t":"single_choice","p":"Which explicit formula gives the total number of dots $u_n$ in Figure $n$?\n\n[Figure: Figure n]","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which explicit formula gives the total number of dots "},{"type":"mathInline","attrs":{"latex":"u_n"}},{"type":"text","text":" in Figure "},{"type":"mathInline","attrs":{"latex":"n"}},{"type":"text","text":"?"}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"Figure n","patterns":[{"label":"Fig. 1 (5)","columns":[{"count":2,"shade":true},{"count":3,"shade":false}]},{"label":"Fig. 2 (8)","columns":[{"count":2,"shade":true},{"count":3,"shade":false},{"count":3,"shade":false}]},{"label":"Fig. 3 (11)","columns":[{"count":2,"shade":true},{"count":3,"shade":false},{"count":3,"shade":false},{"count":3,"shade":false}]}],"version":1}}}]},"e":"Each figure keeps the same column of 2 dark dots and adds one more column of 3 pale dots, so $u_n = 2 + 3n$. Check: $u_1 = 5$, $u_2 = 8$, $u_3 = 11$.","m":1,"df":"easy","tp":"Patterns to formulae","st":"dot pattern to explicit formula","cfg":{"question_number":9,"paper_question_key":9,"paper_section":"A","myp_criterion":"B","criterion_label":"Criterion B — Investigating patterns","criterion_title":"Investigating patterns","difficulty_level":"basic","marks":1,"calculator":true,"calculator_policy":"permitted","assessment_style":"myp_summative","source":"myp5-sequences-and-series-summative-2026"}},{"n":10,"t":"single_choice","p":"An arithmetic series has $u_1 = 6$, $u_{20} = 63$ and $n = 20$ terms. Calculate $S_{20}$.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An arithmetic series has "},{"type":"mathInline","attrs":{"latex":"u_1 = 6"}},{"type":"text","text":", "},{"type":"mathInline","attrs":{"latex":"u_{20} = 63"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"n = 20"}},{"type":"text","text":" terms. Calculate "},{"type":"mathInline","attrs":{"latex":"S_{20}"}},{"type":"text","text":"."}]}]},"e":"$S_n = \\frac{n}{2}(u_1 + u_n) = \\frac{20}{2}(6 + 63) = 10 \\times 69 = 690$.","m":1,"df":"easy","tp":"Arithmetic series","st":"sum from first 